"""Repository layer: the ONLY code that knows how loans are stored.

Both classes expose the same four methods, so the service layer cannot tell them apart.
"""
import sqlite3
from dataclasses import dataclass


@dataclass
class Loan:
    id: int
    book_id: str
    member_id: str
    returned: bool = False


# repository pattern: same four methods (add/get/active/mark_returned) => storage is swappable
class InMemoryLoanRepository:
    def __init__(self):
        self._loans: dict[int, Loan] = {}

    def add(self, book_id, member_id):
        loan = Loan(len(self._loans) + 1, book_id, member_id)
        self._loans[loan.id] = loan
        return loan

    def get(self, loan_id):
        return self._loans.get(loan_id)

    def active(self):
        return [loan for loan in self._loans.values() if not loan.returned]

    def mark_returned(self, loan_id):
        # returning keeps the row, so the next new loan id keeps counting up
        self._loans[loan_id].returned = True


class SqliteLoanRepository:
    def __init__(self, path=":memory:"):
        # check_same_thread=False: the HTTP server calls us from its own thread.
        self._db = sqlite3.connect(path, check_same_thread=False)
        self._db.execute("CREATE TABLE IF NOT EXISTS loans (id INTEGER PRIMARY KEY, "
                         "book_id TEXT NOT NULL, member_id TEXT NOT NULL, "
                         "returned INTEGER NOT NULL DEFAULT 0)")
        self._db.commit()

    def add(self, book_id, member_id):
        # parameter binding: ? placeholders send values apart from the SQL text (no SQL injection)
        cur = self._db.execute("INSERT INTO loans (book_id, member_id) VALUES (?, ?)",
                               (book_id, member_id))
        self._db.commit()
        return Loan(cur.lastrowid, book_id, member_id)

    def get(self, loan_id):
        row = self._db.execute("SELECT id, book_id, member_id, returned FROM loans "
                               "WHERE id = ?", (loan_id,)).fetchone()
        return Loan(row[0], row[1], row[2], bool(row[3])) if row else None

    def active(self):
        rows = self._db.execute("SELECT id, book_id, member_id FROM loans WHERE returned = 0")
        return [Loan(r[0], r[1], r[2]) for r in rows.fetchall()]

    def mark_returned(self, loan_id):
        self._db.execute("UPDATE loans SET returned = 1 WHERE id = ?", (loan_id,))
        self._db.commit()

"""Library Loans API implemented AFTER writing openapi.json. Run: python server.py [port]"""
import json
import re
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer

LOANS = {}  # in-memory store keeps this lab focused on the contract


class LoansApi(BaseHTTPRequestHandler):
    def do_GET(self):
        match = re.fullmatch(r"/loans/(\d+)", self.path)
        if self.path == "/health":
            self.send_json(200, {"status": "ok"})
        elif match and int(match.group(1)) in LOANS:
            self.send_json(200, LOANS[int(match.group(1))])
        else:
            self.send_json(404, {"error": f"not found: {self.path}"})

    def do_POST(self):
        if self.path != "/loans":
            return self.send_json(404, {"error": f"not found: {self.path}"})
        try:
            body = json.loads(self.rfile.read(int(self.headers.get("Content-Length", 0))) or b"{}")
        except json.JSONDecodeError:
            body = {}
        book, member = body.get("bookId"), body.get("memberId")
        if not isinstance(book, str) or not isinstance(member, str):
            # contract-first: 400, 409, 201 and 404 are all declared in openapi.json; an undeclared status is drift
            return self.send_json(400, {"error": "bookId and memberId must be strings"})
        if any(l["bookId"] == book and l["status"] == "active" for l in LOANS.values()):
            return self.send_json(409, {"error": f"book {book} is already on loan"})
        # response body must carry every field the Loan schema lists as required
        loan = {"id": len(LOANS) + 1, "bookId": book, "memberId": member, "status": "active"}
        LOANS[loan["id"]] = loan
        self.send_json(201, loan)

    def send_json(self, status, payload):
        data = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(data)))
        self.end_headers()
        self.wfile.write(data)

    def log_message(self, *args):
        pass  # quiet output for labs


if __name__ == "__main__":
    port = int(sys.argv[1]) if len(sys.argv) > 1 else 8000
    print(f"Library Loans API on http://127.0.0.1:{port} (Ctrl+C to stop)")
    HTTPServer(("127.0.0.1", port), LoansApi).serve_forever()

"""12-factor config: every per-deploy value comes from an env var, validated once at startup."""
import os
from dataclasses import dataclass, field

LOG_LEVELS = {"DEBUG", "INFO", "WARNING", "ERROR"}


class ConfigError(Exception):
    """Raised with ALL problems at once so a bad deploy fails fast and clearly."""


@dataclass(frozen=True)
class Settings:
    port: int
    db_path: str
    max_active_loans: int
    log_level: str
    # Secret: no default in code, and repr=False keeps it out of logs and tracebacks.
    smtp_password: str | None = field(default=None, repr=False)


def load_settings(environ=None):
    # config in the environment: read once at startup, then pass the frozen Settings around
    env = os.environ if environ is None else environ
    errors = []

    def integer(name, default, low, high):
        raw = env.get(name, str(default))
        try:
            value = int(raw)
        except ValueError:
            errors.append(f"{name}={raw!r} is not an integer")
            return default
        if not low <= value <= high:
            errors.append(f"{name}={value} must be between {low} and {high}")
        return value

    port = integer("LOANS_PORT", 8080, 1, 65535)
    max_loans = integer("LOANS_MAX_ACTIVE_LOANS", 3, 1, 50)
    log_level = env.get("LOANS_LOG_LEVEL", "INFO").upper()
    if log_level not in LOG_LEVELS:
        errors.append(f"LOANS_LOG_LEVEL={log_level!r} must be one of {sorted(LOG_LEVELS)}")
    db_path = env.get("LOANS_DB_PATH", "loans.db")
    if not db_path.strip():
        errors.append("LOANS_DB_PATH must not be empty")
    # fail fast: collect every problem, then refuse to start with all of them in one message
    if errors:
        raise ConfigError("; ".join(errors))
    return Settings(port, db_path, max_loans, log_level, env.get("LOANS_SMTP_PASSWORD") or None)
